/* جدول الطلبات — v4 (عقد v68 + الحالة المؤكدة):
   · عمود «قيمة المنتجات الأصلية» = row.productsTotal (خام قبل الخصم).
   · عمود «أساس العمولة» = row.countedBase (بعد الخصم والمرتجع).
   · العمولة تُقرأ من commission كما جاءت — لا تُحسب بضرب النسبة.
   · الشرطة حسب counts فقط: counts===false → "—" حتى لو commission:0.
   · estimated → "~" + شارة "تقديري". تعدد العملات → ترويسة لكل عملة. */
import { rowCurrencyKey } from "../../api/marketers.js";
import { tx, daysAgo } from "./texts.js";

function fmt(n) { return Number(n || 0).toFixed(2); }

function fdate(iso, en) {
  const d = new Date(iso);
  if (isNaN(d)) return { a: String(iso == null ? "" : iso), b: "" };
  const p = function (x) { return String(x).padStart(2, "0"); };
  const a = d.getFullYear() + "/" + p(d.getMonth() + 1) + "/" + p(d.getDate()) + " " + p(d.getHours()) + ":" + p(d.getMinutes());
  const days = Math.floor((Date.now() - d.getTime()) / 864e5);
  let b = "";
  if (days <= 0) b = tx("today", en);
  else if (days === 1) b = tx("day1", en);
  else if (days === 2) b = tx("day2", en);
  else b = daysAgo(days, en);
  return { a: a, b: b };
}

function StatementRow(props) {
  const en = !!props.en;
  const x = props.row || {};
  const f = fdate(x.orderDate, en);
  const est = !!x.estimated;
  const commCell = x.counts ? (
    <span>
      <span className="mk-comm" title={est ? tx("estimatedBadge", en) : undefined}>{est ? "~" : ""}{x.commission == null ? "—" : fmt(x.commission)}</span>
      {est ? <span className="mk-est">{tx("estimatedBadge", en)}</span> : null}
    </span>
  ) : <span className="mk-dash">—</span>;
  return (
    <tr>
      <td data-th={tx("colOrder", en)}>
        <div className="mk-ocode" dir="ltr">{x.orderCode}</div>
        <div className="mk-ono">{tx("orderNo", en)} #{x.orderNo}</div>
      </td>
      <td className="mk-odate" data-th={tx("colDate", en)}>{f.a}{f.b ? <small>{f.b}</small> : null}</td>
      <td data-th={tx("colOriginal", en)}>{est ? <span title={tx("estimatedBadge", en)}>~</span> : null}{fmt(x.productsTotal)}</td>
      <td data-th={tx("colBase", en)}>{est ? <span title={tx("estimatedBadge", en)}>~</span> : null}{x.countedBase == null ? "—" : fmt(x.countedBase)}</td>
      <td className="mk-rate" data-th={tx("colRate", en)}>%{x.rate}</td>
      <td data-th={tx("colComm", en)}>{commCell}</td>
      <td data-th={tx("colStatus", en)}>{x.counts
        ? <span className="mk-pill ok">{tx("isCounted", en)}</span>
        : <span className="mk-pill no">{tx("excluded", en)}</span>}</td>
    </tr>
  );
}

export default function StatementTable(props) {
  const en = !!props.en;
  const rows = Array.isArray(props.rows) ? props.rows : [];
  if (!rows.length) return <p className="mk-hint">{tx("emptyRows", en)}</p>;

  const groups = [];
  const seen = {};
  rows.forEach(function (x) {
    const k = rowCurrencyKey(x);
    if (!seen[k]) { seen[k] = true; groups.push(k); }
  });
  const multi = groups.length > 1;

  function groupName(k) {
    if (k === "main") return tx("baseCurrency", en);
    return tx("currencyLabel", en) + " " + k;
  }

  function body(list) {
    return list.map(function (x, i) {
      return <StatementRow key={String(x.orderCode || x.orderNo || i)} row={x} en={en} />;
    });
  }

  return (
    <div className="mk-tblcard"><div className="mk-tblscroll"><table>
      <thead><tr>
        <th>{tx("colOrder", en)}</th>
        <th>{tx("colDate", en)}</th>
        <th>{tx("colOriginal", en)}</th>
        <th>{tx("colBase", en)}</th>
        <th>{tx("colRate", en)}</th>
        <th>{tx("colComm", en)}</th>
        <th>{tx("colStatus", en)}</th>
      </tr></thead>
      <tbody>
        {!multi ? body(rows) : groups.map(function (g) {
          return [
            <tr className="mk-curhead" key={"h-" + g}><td colSpan={7}>{groupName(g)}</td></tr>
          ].concat(body(rows.filter(function (x) { return rowCurrencyKey(x) === g; })));
        })}
      </tbody>
    </table></div></div>
  );
}
