/* ============================================================
   أطياب الجاسم — صفحة كشف مستحقات المسوّق (رابط فقط، بلا أي زر/رابط لها)
   المسار: /m (إدخال كود) و /m/:code (جلب تلقائي عند التحميل).
   لا تُضف لها أي رابط في الهيدر/القوائم — الدخول بالرابط المباشر فقط.
   ============================================================ */
import { useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useAppDispatch, useAppSelector } from "../redux/hooks.js";
import { fetchStatement, marketerStatementActions, selectMarketerStatement } from "../redux/slices/marketerStatementSlice.js";
import { normCode } from "../api/marketers.js";
import StatementEntry from "../components/Marketer/StatementEntry.jsx";
import StatementWho from "../components/Marketer/StatementWho.jsx";
import StatementStats from "../components/Marketer/StatementStats.jsx";
import StatementTable from "../components/Marketer/StatementTable.jsx";
import { StatementSkeleton } from "../components/Skeletons/index.js";
import { tx } from "../components/Marketer/texts.js";
import "../marketer-statement.css";

const KNOWN_KINDS = ["not_found", "forbidden", "unavailable", "network"];

export default function MarketerStatementPage() {
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) { return s.ui.language; });
  const en = language === "en";
  const params = useParams();
  const nav = useNavigate();
  const code = normCode(params && params.code);
  const st = useAppSelector(selectMarketerStatement);

  /* صفحة مستقلة بلا MainLayout: العنوان + الاتجاه + اللغة هنا مباشرة،
     وتمرير للأعلى عند كل تنقّل بين /m و /m/:code */
  useEffect(function () {
    try { document.title = (en ? "Marketer statement" : "كشف مستحقات المسوّق") + " — " + (en ? "ATYAB AL-JASEM" : "أطياب الجاسم"); } catch (e) {}
    try {
      document.documentElement.dir = en ? "ltr" : "rtl";
      document.documentElement.lang = en ? "en" : "ar";
    } catch (e2) {}
    try { window.scrollTo(0, 0); } catch (e3) {}
  }, [en, code]);

  /* الجلب عند الدخول بالرابط فقط — مع إلغاء عند المغادرة */
  useEffect(function () {
    if (!code) return undefined;
    const p = dispatch(fetchStatement(code));
    return function () { try { p.abort(); } catch (e) {} };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [code, dispatch]);

  function retry() {
    if (code) dispatch(fetchStatement(code));
    else dispatch(marketerStatementActions.resetStatement());
  }
  function otherCode() {
    dispatch(marketerStatementActions.resetStatement());
    nav("/m");
  }

  const kind = KNOWN_KINDS.indexOf(st.errorKind) >= 0 ? st.errorKind : (st.status === "failed" ? "unavailable" : "");

  return (
    <div className="mk-page" dir={en ? "ltr" : "rtl"}>
    <section className="mk" id="marketerStatementView">
      <header className="mk-head">
        <span className="mk-eyebrow">{tx("eyebrow", en)}</span>
        <div className="mk-brand">{tx("brand", en)}</div>
        <h1>{tx("title", en)}</h1>
        <p className="mk-sub">{tx("sub", en)}</p>
      </header>

      {!code ? (
        <StatementEntry en={en} />
      ) : st.status === "loading" && !st.data ? (
        <StatementSkeleton />
      ) : st.status === "failed" ? (
        <div className="mk-card">
          <p className="mk-err show" role="alert">{tx(kind || "unavailable", en)}</p>
          <div className="mk-btnrow">
            <button className="mk-go" type="button" onClick={retry}>{tx("retry", en)}</button>
            <button className="mk-quiet" type="button" onClick={otherCode}>{tx("otherCode", en)}</button>
          </div>
        </div>
      ) : st.data ? (
        <div className="mk-result">
          <StatementWho data={st.data} en={en} />
          <StatementStats data={st.data} en={en} />
          <StatementTable rows={st.data.rows} en={en} />
          {(() => { try { return /[?&]debug=1/.test(window.location.search); } catch (e) { return false; } })() && st.data ? (
          <pre className="mk-debug" dir="ltr">{JSON.stringify(st.data, null, 2)}</pre>
        ) : null}
        <p className="mk-note">{tx("note", en)}</p>
          <button className="mk-quiet center" type="button" onClick={otherCode}>{tx("otherCode", en)}</button>
        </div>
      ) : null}
    </section>
    </div>
  );
}
