/* بطاقات المجاميع — v4 (عقد v68 + الحالة المؤكدة):
   · البطاقة الوسطى «المبيعات المحتسب للعمولة» = countedBaseTotal كما جاء
     من الرد (احتياط productsTotal مع خادم قديم) — بلا تثبيت رقم وبلا اشتقاق.
   · العمولة تُقرأ من totalDue كما جاءت — لا تُعاد حسابها بضرب النسبة.
   · hasEstimates → تنبيه. returnedGoodsTotal>0 → سطر مرتجع.
   · تعدد العملات → مجاميع كل عملة من rows (أساس المحتسب + العمولة). */
import { rowSaleBase, rowCurrencyKey, selectSaleTotal } from "../../api/marketers.js";
import { tx } from "./texts.js";

function fmt(n) { return Number(n || 0).toFixed(2); }

function groupLabel(key, en) {
  if (key === "main") return tx("baseCurrency", en);
  return tx("currencyLabel", en) + " " + key;
}

export default function StatementStats(props) {
  const en = !!props.en;
  const data = props.data || {};
  const rows = Array.isArray(data.rows) ? data.rows : [];

  const warn = data.hasEstimates ? (
    <p className="mk-warn" role="note">{tx("estimatesAlert", en)}</p>
  ) : null;

  const groups = [];
  const seen = {};
  rows.forEach(function (x) {
    const k = rowCurrencyKey(x);
    if (!seen[k]) { seen[k] = true; groups.push(k); }
  });

  if (groups.length > 1) {
    return (
      <div>
        {warn}
        <div className="mk-stats mk-curgrid">
          {groups.map(function (g) {
            const gr = rows.filter(function (x) { return rowCurrencyKey(x) === g; });
            const counted = gr.filter(function (x) { return !!x.counts; });
            let sale = 0, comm = 0;
            counted.forEach(function (x) {
              sale += rowSaleBase(x);
              comm += Number(x.commission || 0);
            });
            return (
              <div className="mk-stat y" key={g}>
                <small>{groupLabel(g, en)}</small>
                <b>{fmt(sale)}</b>
                <span className="mk-lines">
                  {counted.length} {tx("counted", en)} · {tx("perComm", en)} {fmt(comm)}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  const saleTotal = selectSaleTotal(data);
  const ret = Number(data.returnedGoodsTotal || 0);
  return (
    <div>
      {warn}
      <div className="mk-stats">
        <div className="mk-stat w">
          <small>{tx("counted", en)}</small>
          <b>{data.countedOrders != null ? data.countedOrders : "—"}</b>
          <span className="mk-lines">{rows.length} {tx("lines", en)}</span>
        </div>
        <div className="mk-stat g">
          <small>{tx("products", en)}</small>
          <b>{saleTotal != null ? fmt(saleTotal) : "—"}</b>
          {ret > 0 ? <span className="mk-lines">{tx("returnedGoods", en)}: {fmt(ret)}</span> : null}
        </div>
        <div className="mk-stat y">
          <small>{tx("due", en)}</small>
          <b>{data.totalDue != null ? fmt(data.totalDue) : "—"}</b>
        </div>
      </div>
    </div>
  );
}
