/* بطاقة إدخال الكود — تُعرض عند فتح /m بلا كود */
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { tx } from "./texts.js";

function fmtCode(v) {
  return String(v || "").replace(/\s+/g, "").toUpperCase();
}

export default function StatementEntry(props) {
  const en = !!props.en;
  const [code, setCode] = useState(props.initialCode || "");
  const [localErr, setLocalErr] = useState("");
  const nav = useNavigate();

  function submit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const c = fmtCode(code);
    if (!c) { setLocalErr(tx("empty", en)); return; }
    setLocalErr("");
    /* تنقّل هاش (متوافق مع HashRouter المستعمل في المتجر: /#/tracking) نحو رابط الكود الذي يجلب تلقائيًا */
    nav("/m/" + encodeURIComponent(c));
  }

  return (
    <div className="mk-card">
      <h2>{tx("hello", en)} 👋</h2>
      <p className="mk-sub">{tx("entryHint", en)}</p>
      <form onSubmit={submit}>
        <label className="mk-lbl" htmlFor="mkCode">{tx("codeLabel", en)}</label>
        <input
          id="mkCode"
          className="mk-input"
          type="text"
          inputMode="text"
          autoComplete="off"
          dir="ltr"
          value={code}
          onChange={function (e) { setCode(e.target.value); }}
          placeholder="Code"
        />
        {localErr ? <p className="mk-err" role="alert">{localErr}</p> : null}
        <button className="mk-go" type="submit">
          <span>{tx("show", en)}</span>
        </button>
      </form>
    </div>
  );
}
